#[cfg(test)]
mod order_reject_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_order_reject_codec() {
        let original = OrderReject {
            biz_id: 123456,
            biz_pbu: "a".repeat(8),
            cl_ord_id: "a".repeat(10),
            security_id: "a".repeat(12),
            ord_rej_reason: 123456,
            trade_date: 123456,
            transact_time: 123456789,
            user_info: "a".repeat(32),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(OrderRejectRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        OrderReject::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = OrderReject::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

